template:
fn parse(s: &str) -> Result<u16, &'static str> {
    s.parse::<u16>().map_err(|_| "bad")
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_port() -> ⟦ret_type⟧ {
        let p = parse("8080")⟦op⟧;
        assert_eq!(p, 8080);
        Ok(())
    }
}

tests:
#[test]
fn check_parse() {
    assert_eq!(parse("8080"), Ok(8080));
    assert_eq!(parse("invalid"), Err("bad"));
}
